#!/usr/bin/env python3
"""Find all call sites of django.utils.timezone functions in the repo.

Hop 1: direct calls (timezone.<fn>(...) via module import, or <fn>(...) via
       from django.utils.timezone import ...)
Hop 2 (input): a set of wrapper function names to search callers for.
"""
import ast, json, os, sys

ROOT = "/private/tmp/v19-pilot/snapshots/django-dd6f6b1"
TZ_FNS = {
    "get_fixed_timezone", "get_default_timezone", "get_default_timezone_name",
    "get_current_timezone", "get_current_timezone_name", "activate",
    "deactivate", "override", "template_localtime", "localtime", "localdate",
    "now", "is_aware", "is_naive", "make_aware", "make_naive",
}

py_files = []
for dirpath, dirnames, filenames in os.walk(ROOT):
    dirnames[:] = [d for d in dirnames if d not in (".git", "node_modules", "__pycache__", ".tox", "build", "dist")]
    for f in filenames:
        if f.endswith(".py"):
            py_files.append(os.path.join(dirpath, f))

def rel(p):
    return os.path.relpath(p, ROOT)

# collect: file -> list of (line, fn, enclosing_chain, hop)
direct_hits = []   # (file, line, fn, enclosing)
import_hits = []   # files importing the module (for reference)

class Enclosing(ast.NodeVisitor):
    """Track enclosing function stack while walking."""
    def __init__(self, callback):
        self.stack = []
        self.callback = callback
    def visit_FunctionDef(self, node):
        self.stack.append(node.name)
        self.generic_visit(node)
        self.stack.pop()
    visit_AsyncFunctionDef = visit_FunctionDef
    def visit_ClassDef(self, node):
        self.stack.append(node.name)
        self.generic_visit(node)
        self.stack.pop()
    def visit_Call(self, node):
        self.callback(node, list(self.stack))
        self.generic_visit(node)

for path in py_files:
    try:
        with open(path, encoding="utf-8", errors="replace") as fh:
            src = fh.read()
        tree = ast.parse(src)
    except SyntaxError:
        continue
    module_aliases = set()    # names bound to django.utils.timezone module
    direct_names = set()      # directly imported function names
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for a in node.names:
                if a.name == "django.utils.timezone":
                    module_aliases.add(a.asname or "timezone")
        elif isinstance(node, ast.ImportFrom):
            if node.module == "django.utils.timezone" and node.level == 0:
                for a in node.names:
                    if a.name == "timezone":
                        module_aliases.add(a.asname or "timezone")
                    elif a.name in TZ_FNS:
                        direct_names.add(a.asname or a.name)
            elif node.module == "django.utils" and node.level == 0:
                for a in node.names:
                    if a.name == "timezone":
                        module_aliases.add(a.asname or "timezone")
        elif isinstance(node, ast.Import) :
            pass
    if module_aliases or direct_names:
        import_hits.append(rel(path))

    def cb(node, stack):
        f = node.func
        # timezone.<fn>(...)
        if isinstance(f, ast.Attribute) and isinstance(f.value, ast.Name) \
           and f.value.id in module_aliases and f.attr in TZ_FNS:
            direct_hits.append((rel(path), node.lineno, f.attr, stack, "module"))
        # bare <fn>(...) for direct imports
        elif isinstance(f, ast.Name) and f.id in direct_names:
            direct_hits.append((rel(path), node.lineno, f.id, stack, "direct"))

    Enclosing(cb).visit(tree)

out = {
    "import_files": sorted(set(import_hits)),
    "direct_calls": [
        {"file": f, "line": l, "fn": fn, "enclosing": ".".join(e), "mode": m}
        for f, l, fn, e, m in sorted(direct_hits)
    ],
}
json.dump(out, sys.stdout, indent=1)

#!/usr/bin/env python3
"""Verify hop-2 hits: resolve which wrapper def each call site can actually
refer to (import analysis), drop false positives, merge with hop 1."""
import ast, json, os
from collections import defaultdict

ROOT = "/private/tmp/v19-pilot/snapshots/django-dd6f6b1"
hop1 = json.load(open('/tmp/tz_hop1.json'))
hop2 = json.load(open('/tmp/tz_hop2_raw.json'))

def rel(p): return os.path.relpath(p, ROOT)
def modpath(f):  # django/utils/timezone.py -> django.utils.timezone
    return os.path.splitext(f.replace('/', '.'))[0]

# wrapper defs: short name -> list of (file, qualname)
wrappers = defaultdict(list)
for c in hop1['direct_calls']:
    enc = c['enclosing']
    if enc:
        wrappers[enc.split('.')[-1]].append((c['file'], enc))

# per-file import map: name -> set of modules it may come from
def file_imports(path):
    full = os.path.join(ROOT, path)
    try:
        tree = ast.parse(open(full, encoding='utf-8', errors='replace').read())
    except Exception:
        return {}
    m = defaultdict(set)
    for node in ast.walk(tree):
        if isinstance(node, ast.ImportFrom) and node.module:
            for a in node.names:
                m[a.asname or a.name].add(node.module)
        elif isinstance(node, ast.Import):
            for a in node.names:
                m[(a.asname or a.name).split('.')[0]].add(a.name)
    return m

import_cache = {}
def imports_for(path):
    if path not in import_cache:
        import_cache[path] = file_imports(path)
    return import_cache[path]

verified, rejected = [], []
for h in hop2:
    w = h['wrapper']
    defs = wrappers[w]
    f = h['file']
    ok = False
    why = ""
    for dfile, qual in defs:
        is_method = '.' in qual  # Class.method
        if dfile == f:
            ok = True; why = f"local:{qual}"; break
        if is_method:
            # method: accept self./cls. calls in def file, or receiver heuristic kept from scan
            if h['recv'].startswith(('self.', 'cls.')) or any(
                    x in h['recv'] for x in ('Model', 'Field', 'Encoder', 'Response', 'Session',
                                             'Backend', 'Cache', 'Operations', 'Storage', 'Feed',
                                             'editor', 'instance', 'obj', 'field', 'session', 'task')):
                ok = True; why = f"method:{qual}"; break
        else:
            imps = imports_for(f)
            dmod = modpath(dfile)
            # direct from-import of wrapper's module
            if dmod in imps.get(w, ()) or dmod.endswith('.' + imps.get(w, {''}).pop() if imps.get(w) else False):
                ok = True; why = f"import:{qual}"; break
            # from <module> import name  where module == def module
            mods = imps.get(w, set())
            if dmod in mods or any(m == dmod for m in mods):
                ok = True; why = f"import:{qual}"; break
            # relative import: from .mod import w  (module stored as 'mod' textually?)
            # ast gives module text as written (e.g. 'django.utils.timesince' only if absolute)
            # catch same-package relative: module attr like 'utils.timesince'
            parts = dmod.split('.')
            for m in mods:
                if m.split('.') == parts[-2:] if len(parts) >= 2 else False:
                    ok = True; why = f"relimport:{qual}"; break
            if ok: break
            # module-attr style: timesince.timesince(...)
            if any(m.split('.')[-1] == dmod.split('.')[-1] for m in imps.get(w, ())):
                ok = True; why = f"modattr:{qual}"; break
    (verified if ok else rejected).append({**h, "why": why})

json.dump(verified, open('/tmp/tz_hop2_verified.json', 'w'), indent=1)
print("verified hop2:", len(verified), "files:", len({h['file'] for h in verified}))
print("rejected:", len(rejected))
print("\n-- sample rejections --")
for r in rejected[:15]:
    print(" ", r['file'] + ':' + str(r['line']), r['wrapper'], '|', r['recv'][:40])
